  ('purple-shamrock', 'Purple Shamrock', 'Oxalis triangularis', 'Oxalidaceae', 'easy'::public.care_difficulty, 'bright_indirect'::public.light_level, 7, 5, 12, 'Lightly moist; leaves fold shut at night, which is normal.', 35, 55, 80, 'Balanced feed monthly in growing season', 'Well-draining potting mix', true, true, 'clumping'::public.growth_habit, '6-12 in', '{"dormancy mistaken for death","legginess in low light","bulb rot"}'::text[], 'Bulb division', 'May go fully dormant: cut back, keep dry 4-6 weeks, then resume'),
  ('venus-flytrap', 'Venus Flytrap', 'Dionaea muscipula', 'Droseraceae', 'hard'::public.care_difficulty, 'direct_sun'::public.light_level, 3, 2, 5, 'Distilled or rain water ONLY; tap water kills it. Keep tray of water beneath.', 50, 40, 90, 'Never fertilize; it feeds on insects', 'Peat and perlite only, no nutrients', false, false, 'rosette'::public.growth_habit, '4-6 in', '{"death from tap water minerals","traps blackening from being triggered for fun","skipping winter dormancy"}'::text[], 'Division or leaf pulling', 'Requires 3-4 months dormancy at 35-50F or it dies within 2 years'),
  ('nepenthes', 'Tropical Pitcher Plant', 'Nepenthes spp.', 'Nepenthaceae', 'hard'::public.care_difficulty, 'bright_indirect'::public.light_level, 3, 2, 6, 'Distilled or rain water only; keep media damp, never flooded.', 70, 60, 85, 'Occasional insect in a pitcher; no root feed', 'Sphagnum and perlite mix', false, false, 'vining'::public.growth_habit, '1-3 ft', '{"no pitchers below 60% humidity","mineral burn from tap water","dried-out pitchers"}'::text[], 'Stem cutting', 'Maintain humidity; growth slows and pitchering may pause'),
