  ('purple-passion-plant', 'Purple Passion Plant', 'Gynura aurantiaca', 'Asteraceae', 'easy'::public.care_difficulty, 'bright_indirect'::public.light_level, 6, 4, 10, 'Lightly moist; water at the base, fuzzy leaves spot easily.', 45, 60, 80, 'Balanced feed monthly in growing season', 'Standard potting mix', false, false, 'trailing'::public.growth_habit, '1-2 ft', '{"losing purple fuzz in low light","foul-smelling flowers (pinch them off)","legginess"}'::text[], 'Stem cutting in water', 'Stretch interval ~30%; pinch to keep bushy'),
  ('coleus', 'Coleus', 'Plectranthus scutellarioides', 'Lamiaceae', 'easy'::public.care_difficulty, 'bright_indirect'::public.light_level, 4, 3, 8, 'Keep moist; wilts fast and dramatically.', 45, 60, 85, 'Balanced feed every 2 weeks in growing season', 'Rich moisture-retentive mix', true, true, 'upright'::public.growth_habit, '1-2 ft', '{"legginess if not pinched","color fade in low light","collapse when dry"}'::text[], 'Stem cutting in water (very fast)', 'Pinch flower spikes; reduce water ~30%'),
  ('callisia-repens', 'Turtle Vine', 'Callisia repens', 'Commelinaceae', 'easy'::public.care_difficulty, 'bright_indirect'::public.light_level, 6, 4, 11, 'Lightly moist; fast spreading ground cover.', 40, 55, 85, 'Balanced feed monthly in growing season', 'Standard potting mix', true, true, 'trailing'::public.growth_habit, '1-3 ft strands', '{"bald centers","color fade in low light","stem rot"}'::text[], 'Stem cutting', 'Stretch interval ~30%; trim back'),
  ('selaginella', 'Spike Moss', 'Selaginella kraussiana', 'Selaginellaceae', 'hard'::public.care_difficulty, 'low_medium'::public.light_level, 3, 2, 5, 'Must stay constantly damp; dies fast in dry air.', 70, 60, 78, 'Very dilute feed every 8 weeks', 'Moisture-retentive peaty mix', false, false, 'creeping'::public.growth_habit, '2-4 in tall mat', '{"browning in open rooms","crisping within hours of drying","needs terrarium"}'::text[], 'Division or stem cutting', 'Terrarium only; keep off heated air'),
  ('clivia', 'Clivia', 'Clivia miniata', 'Amaryllidaceae', 'moderate'::public.care_difficulty, 'medium'::public.light_level, 12, 8, 22, 'Let dry well down; needs a dry cool rest to bloom.', 35, 50, 80, 'Balanced feed monthly in growing season', 'Well-draining potting mix', true, true, 'clumping'::public.growth_habit, '1-2 ft', '{"no blooms without cool dry rest","rot from overwatering","slow to mature"}'::text[], 'Offset division', '6-8 weeks at 50-55F with minimal water to set flowers'),
  ('calla-lily', 'Calla Lily', 'Zantedeschia aethiopica', 'Araceae', 'moderate'::public.care_difficulty, 'bright_indirect'::public.light_level, 5, 3, 9, 'Keep consistently moist during growth and bloom.', 45, 55, 80, 'High-phosphorus feed every 2 weeks when blooming', 'Rich moisture-retentive mix', true, true, 'clumping'::public.growth_habit, '1-3 ft', '{"rhizome rot","dormancy mistaken for death","no rebloom without rest"}'::text[], 'Rhizome division', 'Dormant: withhold water 2-3 months, then resume'),
  ('meyer-lemon', 'Meyer Lemon', 'Citrus × meyeri', 'Rutaceae', 'hard'::public.care_difficulty, 'direct_sun'::public.light_level, 6, 4, 11, 'Deep water when top 2 in dry; needs 6+ hours direct sun.', 45, 55, 85, 'Citrus-specific feed every 4-6 weeks year round', 'Well-draining citrus mix', false, false, 'tree'::public.growth_habit, '3-6 ft indoors', '{"leaf drop from light or water swings","spider mites and scale","iron chlorosis (yellow leaves, green veins)"}'::text[], 'Cutting or grafting', 'Max light, cooler temps, reduce water ~30%; hand-pollinate indoor blooms'),
  ('rosemary', 'Rosemary', 'Salvia rosmarinus', 'Lamiaceae', 'hard'::public.care_difficulty, 'direct_sun'::public.light_level, 7, 5, 12, 'Dry top 2 in; needs excellent airflow or it molds.', 30, 40, 85, 'Light feed every 8 weeks in growing season', 'Gritty fast-draining mix', false, false, 'shrub'::public.growth_habit, '1-3 ft', '{"powdery mildew indoors","sudden death from root rot","needs 6+ hours sun"}'::text[], 'Stem cutting', 'Cool bright spot with airflow; reduce water ~30%'),
  ('basil', 'Basil', 'Ocimum basilicum', 'Lamiaceae', 'moderate'::public.care_difficulty, 'direct_sun'::public.light_level, 2, 1, 4, 'Keep evenly moist; wilts within a day of drying.', 40, 60, 90, 'Balanced feed every 2-3 weeks in growing season', 'Rich moisture-retentive potting mix', false, false, 'upright'::public.growth_habit, '1-2 ft', '{"bolting to flower (pinch tips)","fungus gnats","legginess without 6h sun"}'::text[], 'Stem cutting in water or seed', 'Needs grow light indoors; treat as annual'),
  ('mint', 'Mint', 'Mentha spicata', 'Lamiaceae', 'easy'::public.care_difficulty, 'bright_indirect'::public.light_level, 3, 2, 6, 'Keep moist; thirsty and vigorous.', 40, 50, 85, 'Balanced feed monthly in growing season', 'Rich moisture-retentive potting mix', false, false, 'creeping'::public.growth_habit, '1-2 ft', '{"aggressive runners taking over pots","rust fungus","legginess"}'::text[], 'Stem cutting in water or runner division', 'Growth slows; cut back hard and reduce water ~40%')
on conflict (slug) do update set
  common_name = excluded.common_name,
  scientific_name = excluded.scientific_name,
  family = excluded.family,
  difficulty = excluded.difficulty,
  light = excluded.light,
  water_days_baseline = excluded.water_days_baseline,
  water_days_min = excluded.water_days_min,
  water_days_max = excluded.water_days_max,
  water_notes = excluded.water_notes,
  humidity_min_pct = excluded.humidity_min_pct,
  temp_min_f = excluded.temp_min_f,
  temp_max_f = excluded.temp_max_f,
  fertilizer = excluded.fertilizer,
  soil = excluded.soil,
  is_toxic_to_cats = excluded.is_toxic_to_cats,
  is_toxic_to_dogs = excluded.is_toxic_to_dogs,
  growth_habit = excluded.growth_habit,
  mature_size = excluded.mature_size,
  common_problems = excluded.common_problems,
  propagation = excluded.propagation,
  winter_adjustment = excluded.winter_adjustment,
  updated_at = now();

-- ---------------------------------------------------------------------------
-- Retire the Perenual rows.
--
-- They are identifiable by slug is null. The sample plants from
-- 20260201182810_sample_data.sql reference them, so repoint those first or the
-- delete fails on my_plants_dim_species_id_fkey.
-- ---------------------------------------------------------------------------

update public.my_plants_dim m
set species_id = (
  select s.species_id
  from public.species_dim s
  where s.slug is not null
  order by random()
  limit 1
)
where m.species_id in (
  select species_id from public.species_dim where slug is null
);

delete from public.species_dim where slug is null;

-- ---------------------------------------------------------------------------
-- Tighten now that every row is curated.
-- ---------------------------------------------------------------------------

alter table public.species_dim alter column slug       set not null;
alter table public.species_dim alter column light      set not null;
alter table public.species_dim alter column difficulty set not null;

alter table public.species_dim validate constraint species_water_band_ordered;
alter table public.species_dim validate constraint species_water_band_positive;
alter table public.species_dim validate constraint species_humidity_pct_range;
alter table public.species_dim validate constraint species_temp_range_ordered;
